@layer reset, base, components, utilities;

@layer base {
  #main-heading { color: blue; }
}
@layer utilities {
  .red-text { color: red; }
}

.parent-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}
.child-item {
  grid-column: span 3;
  display: grid;
  grid-template-columns: subgrid;
}
